package tw.radar.shortscan;

import android.app.*;import android.content.*;import android.graphics.PixelFormat;import android.media.AudioAttributes;import android.os.*;import android.provider.Settings;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import java.util.*;import java.time.*;import org.json.*;import okhttp3.*;

public class RadarService extends Service {
 static volatile String status="尚未啟動",feed="尚未啟動",error="",lastSignal="",activityText="",lastStats="";static volatile boolean running=false;static volatile long latency=-1;
 static final MonitorState MON=new MonitorState();
 static final String PREF="radar",CHANNEL="radar_service",ALERT="radar_alert";
 private final Handler h=new Handler(Looper.getMainLooper());private final HashMap<String,Long> spoken=new HashMap<>();private final OkHttpClient client=new OkHttpClient.Builder().pingInterval(10,java.util.concurrent.TimeUnit.SECONDS).build();
 private WebSocket ws;private long lastPacket;private long started;private int generation=0,attempt=0;private boolean demo=true,ttsReady=false,mini=false,wasSession=false;private TextToSpeech tts;private PowerManager.WakeLock wake;private WindowManager wm;private LinearLayout overlay;private WindowManager.LayoutParams lp;private JSONObject latest;private android.content.SharedPreferences p;private NotificationManager nm;
 @Override public void onCreate(){super.onCreate();p=getSharedPreferences(PREF,MODE_PRIVATE);wm=(WindowManager)getSystemService(WINDOW_SERVICE);nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"雷達掃描服務",NotificationManager.IMPORTANCE_LOW));NotificationChannel a=new NotificationChannel(ALERT,"轉弱訊號提醒",NotificationManager.IMPORTANCE_HIGH);a.enableVibration(false);a.setSound(null,null);nm.createNotificationChannel(a);tts=new TextToSpeech(this,code->{if(code==TextToSpeech.SUCCESS){int result=tts.setLanguage(Locale.TAIWAN);ttsReady=result>=TextToSpeech.LANG_AVAILABLE;MON.tts=ttsReady;tts.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ASSISTANCE_NAVIGATION_GUIDANCE).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());}});}
 private Notification notification(String title,String detail,String channel){Intent i=new Intent(this,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,RadarService.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,channel).setSmallIcon(R.drawable.ic_radar).setContentTitle(title).setContentText(detail).setStyle(new Notification.BigTextStyle().bigText(detail)).setContentIntent(pi).addAction(0,"停止雷達",stop).setOngoing(CHANNEL.equals(channel)).build();}
 @Override public int onStartCommand(Intent i,int flags,int id){String act=i==null?"START":i.getAction();if("STOP".equals(act)){stopSelf();return START_NOT_STICKY;}if("SAMPLE".equals(act)){if(running&&demo)sample();return START_NOT_STICKY;}if("SETTINGS".equals(act)){if(running)sendSettings();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;
  running=true;demo=p.getBoolean("demo",true);started=SystemClock.elapsedRealtime();MON.reset(demo,started);MON.tts=ttsReady;log("背景服務啟動"+(demo?"（模擬）":""));status=demo?"本機模擬模式":"連線中";feed=demo?"模擬心跳正常":"等待後端行情";error="";startForeground(101,notification("盤中做空雷達",status,CHANNEL));
  PowerManager pm=getSystemService(PowerManager.class);wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"ShortRadar:session");wake.setReferenceCounted(false);wake.acquire(5*60*60*1000L);if(!demo)connect();h.post(monitor);return START_NOT_STICKY;
 }
 static boolean marketWindow(){ZonedDateTime z=ZonedDateTime.now(ZoneId.of("Asia/Taipei"));int m=z.getHour()*60+z.getMinute();return z.getDayOfWeek().getValue()<=5&&m>=540&&m<=810;}
 private final Runnable monitor=new Runnable(){public void run(){if(!running)return;MON.tick=SystemClock.elapsedRealtime();MON.wake=wake!=null&&wake.isHeld();if(!demo){if(marketWindow())wasSession=true;else if(wasSession){stopSelf();return;}if(ws!=null&&SystemClock.elapsedRealtime()-lastPacket>15000){error="手機至後端 15 秒無封包";status="手機連線中斷";reconnect(generation);}if(ws!=null){try{ws.send(new JSONObject().put("type","ping").put("sent",System.currentTimeMillis()).toString());}catch(Exception ignored){}}}else{status="本機模擬｜未連實盤";feed="模擬心跳正常";activityText="測試股：無新成交，不影響心跳";}if(SystemClock.elapsedRealtime()-started>5*60*60*1000L){stopSelf();return;}nm.notify(101,notification("盤中雷達服務",MON.state(SystemClock.elapsedRealtime(),running,marketWindow(),p.getString("url","").startsWith("wss://"))+"｜封包 "+MON.packets+"｜運算 "+(MON.engineFresh(SystemClock.elapsedRealtime())?MON.evaluations:"未回報"),CHANNEL));h.postDelayed(this,5000);}};
 private void connect(){if(!running||demo)return;int g=++generation;String url=p.getString("url","").trim();if(!url.startsWith("wss://")){status="請設定 wss:// 後端網址";error="正式模式只允許 TLS";return;}try{lastPacket=SystemClock.elapsedRealtime();Request req=new Request.Builder().url(url).header("Authorization","Bearer "+p.getString("token","")).build();ws=client.newWebSocket(req,new WebSocketListener(){public void onOpen(WebSocket s,Response r){h.post(()->{if(g!=generation)return;lastPacket=SystemClock.elapsedRealtime();attempt=0;MON.socket=true;log("手機 WebSocket 已開啟");status="後端已連線";sendSettings();});}public void onMessage(WebSocket s,String text){h.post(()->{if(g!=generation)return;lastPacket=SystemClock.elapsedRealtime();MON.packet=lastPacket;MON.packets++;try{receive(new JSONObject(text));}catch(Exception e){error="封包格式錯誤";}});}public void onFailure(WebSocket s,Throwable e,Response r){h.post(()->{if(g==generation){error="後端連線失敗："+e.getClass().getSimpleName();reconnect(g);}});}public void onClosed(WebSocket s,int code,String reason){h.post(()->{if(g==generation)reconnect(g);});}});}catch(Exception e){error="後端網址無效";status="設定有誤";}}
 private void reconnect(int g){if(g!=generation||!running)return;generation++;MON.invalidate();MON.reconnects++;log("後端斷線，嘗試重連");if(ttsReady&&p.getBoolean("voice",true)&&SystemClock.elapsedRealtime()-lastWarn>=60000){lastWarn=SystemClock.elapsedRealtime();tts.speak("雷達後端連線中斷，正在重連",TextToSpeech.QUEUE_ADD,null,"disconnect");}if(ws!=null){ws.cancel();ws=null;}status="手機連線中斷｜重連中";feed="後端行情狀態未知";int wait=Math.min(60,1<<Math.min(attempt++,6));int next=generation;h.postDelayed(()->{if(running&&generation==next)connect();},wait*1000L);}
 private void sendSettings(){if(demo||ws==null)return;try{JSONArray w=new JSONArray();for(String x:p.getString("watch","2454,2330,2327,3037,3711").split("[,，\\s]+"))if(!x.isEmpty())w.put(x);JSONObject cfg=new JSONObject(p.getString("config","{}"));ws.send(new JSONObject().put("type","settings").put("mode",p.getString("mode","mixed")).put("watch",w).put("settings",cfg).toString());}catch(Exception e){error="設定無法傳送";}}
 static String sourceName(String s){switch(s){case "fubon":return "富邦 Neo";case "fugle":return "富果";case "demo":return "模擬";default:return "尚未取得";}}
 private long lastWarn=-60000;private void log(String text){MON.event(java.time.LocalTime.now(java.time.ZoneId.of("Asia/Taipei")).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss"))+"  "+text);}
 private void receive(JSONObject j){String type=j.optString("type");if("telemetry".equals(type)){MON.engine(j,SystemClock.elapsedRealtime());return;}if("evaluation".equals(type)){if(MON.engineFresh(SystemClock.elapsedRealtime())&&j.has("demo")&&!j.optBoolean("demo",true))log("後端運算 "+j.optString("symbol")+" "+j.optInt("hits",-1)+"/5");return;}if("status".equals(type)){boolean changed=MON.hasFeed&&MON.feedOk!=j.optBoolean("feed_ok");MON.report(j,SystemClock.elapsedRealtime());if(changed){log(MON.feedOk?"行情心跳恢復":"行情心跳異常");if(!MON.feedOk&&!MON.backendDemo&&ttsReady&&p.getBoolean("voice",true)&&SystemClock.elapsedRealtime()-lastWarn>=60000){lastWarn=SystemClock.elapsedRealtime();tts.speak("行情來源異常",TextToSpeech.QUEUE_ADD,null,"feed");}}status="手機已連後端";if(j.optBoolean("demo"))status="後端模擬資料";feed=sourceName(j.optString("source"))+"｜"+(j.optBoolean("feed_ok")?"心跳正常 · "+(j.isNull("rtt_ms")?"—":j.optInt("rtt_ms")+" ms"):"行情未就緒／中斷");error=j.optString("feed_error");StringBuilder a=new StringBuilder("已訂閱 "+j.optInt("count")+"/"+j.optInt("expected_count")+"｜連線 "+j.optInt("connections")+"｜切換 "+j.optInt("switches")+"\n漏斗 "+j.optInt("pool_count")+"｜排行 "+(j.optBoolean("rank_fresh")?"有效":"未取得")+"\n");JSONArray rows=j.optJSONArray("stocks");if(rows!=null)for(int k=0;k<rows.length();k++){JSONObject x=rows.optJSONObject(k);if(x!=null)a.append(x.optString("symbol")).append(" ").append(x.optString("name")).append("  ").append(Ui.num(x,"price")).append("  ").append(sourceName(x.optString("quote_source"))).append("  ").append(x.optString("activity")).append(x.optBoolean("complete")?"":"／資料缺口").append("\n");}activityText=a.toString();}else if("error".equals(type)){error=j.optString("message");}else if("settings_ack".equals(type)){error="";}else if("signal".equals(type)){if(j.optBoolean("demo")||marketWindow())alert(j);}}
 private void sample(){alert(Ui.sample());}
 private void alert(JSONObject j){if(j.optBoolean("demo")){MON.demoSignals++;log("模擬訊號 "+j.optString("symbol"));}else {MON.signals++;log("正式訊號 "+j.optString("symbol")+" "+j.optInt("hits")+"/5");}latest=j;lastSignal=j.toString();long received=j.optLong("received_ms",0);latency=received>0?System.currentTimeMillis()-received:-1;if(Settings.canDrawOverlays(this)&&p.getBoolean("overlay",true)){mini=false;renderOverlay();}else nm.notify(102,notification((j.optBoolean("demo")?"【模擬】":"")+j.optString("name")+"｜轉弱確認",Ui.reasons(j),ALERT));
  long n=SystemClock.elapsedRealtime();String sym=j.optString("symbol");Long before=spoken.get(sym);if(before==null||n-before>=300000){spoken.put(sym,n);if(p.getBoolean("voice",true)&&ttsReady){String name=p.getBoolean("nameVoice",true)?j.optString("name"):sym;tts.speak((j.optBoolean("demo")?"模擬訊號，":"")+name+"，轉弱確認，"+Ui.reasons(j),TextToSpeech.QUEUE_FLUSH,null,"signal-"+n);}if(p.getBoolean("vibrate",true)){Vibrator v=Build.VERSION.SDK_INT>=31?getSystemService(VibratorManager.class).getDefaultVibrator():getSystemService(Vibrator.class);if(v!=null&&v.hasVibrator())v.vibrate(VibrationEffect.createWaveform(new long[]{0,200,100,400},-1));}}
 }
 private void renderOverlay(){if(latest==null)return;try{if(overlay!=null){wm.removeView(overlay);overlay=null;}if(lp==null){lp=new WindowManager.LayoutParams(Ui.dp(this,292),-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.START;lp.x=Ui.dp(this,12);lp.y=Ui.dp(this,100);}lp.width=Ui.dp(this,mini?64:292);overlay=Ui.card(this);overlay.setElevation(Ui.dp(this,10));TextView handle=Ui.text(this,mini?"雷達 ↗":(latest.optBoolean("demo")?"【模擬】":"")+latest.optString("name")+"｜轉弱確認",mini?13:17,Ui.MINT,true);overlay.addView(handle);handle.setOnTouchListener(new View.OnTouchListener(){float x,y;int ox,oy;boolean moved;public boolean onTouch(View v,android.view.MotionEvent e){switch(e.getAction()){case MotionEvent.ACTION_DOWN:x=e.getRawX();y=e.getRawY();ox=lp.x;oy=lp.y;moved=false;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-x,dy=e.getRawY()-y;if(Math.abs(dx)+Math.abs(dy)>Ui.dp(RadarService.this,5))moved=true;if(moved){lp.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-lp.width,ox+(int)dx));lp.y=Math.max(0,Math.min(getResources().getDisplayMetrics().heightPixels-Ui.dp(RadarService.this,80),oy+(int)dy));wm.updateViewLayout(overlay,lp);}return true;case MotionEvent.ACTION_UP:if(!moved){if(mini){mini=false;renderOverlay();}else{Intent i=new Intent(RadarService.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);}}return true;}return false;}});
  if(!mini){overlay.addView(Ui.text(this,latest.optInt("hits")+" / 5  ·  "+Ui.reasons(latest),12,Ui.FG,false));overlay.addView(Ui.text(this,"現價 "+Ui.num(latest,"price")+"  |  VWAP "+Ui.num(latest,"vwap"),14,Ui.FG,true));overlay.addView(Ui.text(this,"防守 A "+Ui.num(latest,"stop_a")+"  B "+Ui.num(latest,"stop_b"),13,Ui.GOLD,true));int color=Boolean.FALSE.equals(latest.opt("daytrade"))||Boolean.FALSE.equals(latest.opt("below_flat"))?Ui.RED:Ui.MUTED;overlay.addView(Ui.text(this,"先賣後買："+Ui.yes(latest,"daytrade")+"｜平盤下融券："+Ui.yes(latest,"below_flat")+"\n券源："+Ui.borrow(latest),12,color,false));overlay.addView(Ui.text(this,"資格："+latest.optString("qualification_source","未知")+"\n待回測訊號，非必然下跌保證",10,Ui.MUTED,false));Button b=Ui.button(this,"收合氣泡");b.setOnClickListener(v->{mini=true;renderOverlay();});overlay.addView(b);}wm.addView(overlay,lp);}catch(Exception e){overlay=null;error="浮窗無法顯示，請檢查權限";nm.notify(102,notification("轉弱訊號",Ui.reasons(latest),ALERT));}}
 @Override public void onTimeout(int startId,int fgsType){stopSelf();}
 @Override public void onDestroy(){running=false;MON.invalidate();MON.tts=false;MON.wake=false;log("背景服務停止");generation++;h.removeCallbacksAndMessages(null);if(ws!=null)ws.cancel();client.dispatcher().executorService().shutdown();if(overlay!=null)try{wm.removeView(overlay);}catch(Exception ignored){}if(tts!=null){tts.stop();tts.shutdown();}if(wake!=null&&wake.isHeld())wake.release();status="已停止";feed="未監控";stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
